{
  "interpretation": {
    "name": "TightenForkliftFastenersLine3",
    "scope": {"line": 3, "station": "st3", "tool": "NR7", "variant": "F35"},
    "goal": "Fetch the F35 tightening program, bring nutrunner NR7 from the crib to station st3, tighten, evaluate and record the result, then return the tool to the crib.",
    "constraints": [
      "get-program is executed first, before any tool movement",
      "NR7 is reserved before any tool use and released after it has been returned to the crib",
      "transport-tool is delegated to agvexecutor",
      "NR7 is at st3 before configure-tool and tighten-fasteners",
      "Torque and tolerance come only from get-program, never as literals",
      "The tightening is evaluated and recorded (quality policy)",
      "Every tool-using Step depends on reserve-tool so that the lease is renewed before use"
    ],
    "preference": "",
    "priority": "normal",
    "horizon": "single execution, now",
    "requested_capabilities": [],
    "omit_services": []
  },
  "recipe": {
    "name": "line3-nr7-tightening-f35",
    "first_action": "prepare",
    "actions": [
      {
        "name": "prepare",
        "next": "deliver",
        "steps": [
          {
            "name": "get-program",
            "service": "get-program",
            "next": ["reserve-tool"],
            "dep": [],
            "executor": null,
            "params": {}
          },
          {
            "name": "reserve-tool",
            "service": "reserve-tool",
            "next": [],
            "dep": [],
            "executor": null,
            "params": {}
          }
        ]
      },
      {
        "name": "deliver",
        "next": "tighten",
        "steps": [
          {
            "name": "transport-to-station",
            "service": "transport-tool",
            "next": [],
            "dep": ["reserve-tool"],
            "executor": "agvexecutor",
            "params": {"to": "station"}
          }
        ]
      },
      {
        "name": "tighten",
        "next": "return",
        "steps": [
          {
            "name": "configure-tool",
            "service": "configure-tool",
            "next": ["tighten-fasteners"],
            "dep": ["get-program", "reserve-tool"],
            "executor": null,
            "params": {}
          },
          {
            "name": "tighten-fasteners",
            "service": "tighten-fasteners",
            "next": ["evaluate-tightening", "record-tightening"],
            "dep": ["configure-tool", "reserve-tool"],
            "executor": null,
            "params": {}
          },
          {
            "name": "evaluate-tightening",
            "service": "evaluate-tightening",
            "next": [],
            "dep": ["tighten-fasteners", "get-program"],
            "executor": null,
            "params": {}
          },
          {
            "name": "record-tightening",
            "service": "record-tightening",
            "next": [],
            "dep": ["tighten-fasteners"],
            "executor": null,
            "params": {}
          }
        ]
      },
      {
        "name": "return",
        "next": null,
        "steps": [
          {
            "name": "transport-to-crib",
            "service": "transport-tool",
            "next": ["release-tool"],
            "dep": ["reserve-tool"],
            "executor": "agvexecutor",
            "params": {"to": "crib"}
          },
          {
            "name": "release-tool",
            "service": "release-tool",
            "next": [],
            "dep": ["reserve-tool"],
            "executor": null,
            "params": {}
          }
        ]
      }
    ]
  }
}
